def find_shift(frow, crow, W):
    res=[]
    for k in range(W):
        if all(frow[(c-k)%W]==crow[c] for c in range(W)):
            res.append(k)  # crow = frow shifted right by k (cyclic)
    return res
for i,cr in enumerate(C):
    nz=[c for c,v in enumerate(cr) if v]
