    crw=cr[:width]+[0]*(28-width)  # pad
    matches=[]
    for j,fr in enumerate(F):
        for k in find_shift(fr,crw,28):
            matches.append((j,k))
    print('C row',i,'width',width,'matches (Frow,shift):',matches)
